PHONEMES=[
('p','p','pig','🐖','Press your lips together. Open them with a little puff.','closed'),('b','b','bat','🦇','Close your lips. Open them and feel your voice buzz.','closed'),('t','t','tap','👆','Touch the ridge behind your top teeth with your tongue. Let go.','teeth'),('d','d','dog','🐕','Touch behind your top teeth. Let go with your voice on.','teeth'),('k','c, k, ck','cat','🐈','Lift the back of your tongue. Let out a short puff.','open'),('g','g','goat','🐐','Lift the back of your tongue. Let go with a gentle buzz.','open'),('f','f, ff, ph','fish','🐟','Touch your top teeth to your bottom lip. Blow softly.','teeth'),('v','v','van','🚐','Top teeth touch your bottom lip. Turn your voice on.','teeth'),('θ','th','thin','🪶','Let your tongue peek between your teeth. Blow gently.','tongue'),('ð','th','this','👉','Let your tongue peek between your teeth. Add a gentle buzz.','tongue'),('s','s, ss, c','sun','☀️','Keep your tongue behind your teeth. Send out a thin stream of air.','teeth'),('z','z, zz, s','zoo','🦁','Keep your teeth close. Make a soft buzzing sound.','teeth'),('ʃ','sh, ti','ship','🚢','Round your lips a little. Blow as if asking for quiet.','round'),('ʒ','s, si','treasure','💎','Round your lips. Make the middle sound in treasure with a buzz.','round'),('h','h','hat','🎩','Open your mouth. Breathe out softly.','open'),('m','m, mm','moon','🌙','Close your lips. Hum gently through your nose.','closed'),('n','n, nn','net','🥅','Put your tongue behind your top teeth. Hum through your nose.','teeth'),('ŋ','ng, n','ring','💍','Lift the back of your tongue. Hum the last sound in ring.','open'),('l','l, ll','leaf','🍃','Touch your tongue behind your top teeth. Let your voice flow.','teeth'),('r','r, rr','rain','🌧️','Curl your tongue slightly back. Keep it away from your teeth.','round'),('j','y','yellow','🟡','Lift the middle of your tongue. Glide into the next sound.','smile'),('w','w, wh','water','💧','Round both lips. Glide smoothly into the word.','round'),('tʃ','ch, tch','chick','🐤','Touch your tongue behind your teeth. Release with a short sh sound.','round'),('dʒ','j, g, dge','jam','🍓','Start with your tongue behind your teeth. Release with a buzzing sound.','round'),
('æ','a','cat','🐈','Open your mouth wide. Keep your tongue low at the front.','open'),('e','e, ea','hen','🐔','Open your mouth a little. Relax your lips.','open'),('ɪ','i','pig','🐖','Relax your lips and make a short sound.','smile'),('ɒ','o','dog','🐕','Round your lips and keep the sound short.','round'),('ʌ','u, o','sun','☀️','Relax your mouth. Open it for a short sound.','open'),('ʊ','oo, u','book','📚','Round your lips gently. Keep the sound short and relaxed.','round'),('ə','a, er','sofa','🛋️','Relax your mouth completely. Make a tiny soft uh sound.','open'),('iː','ee, ea, e','sheep','🐑','Smile a little. Keep your tongue high. Hold the sound.','smile'),('ɑː','ar, a','car','🚗','Open wide and let your tongue rest low. Hold the sound.','open'),('ɔː','or, aw, au','fork','🍴','Round your lips. Hold the sound gently.','round'),('uː','oo, ue, ew','moon','🌙','Round your lips forward. Hold the sound.','round'),('ɜː','ir, er, ur','bird','🐦','Relax your lips and hold the middle sound in bird.','open'),('eɪ','ai, ay, a-e','rain','🌧️','Start with your mouth open a little. Glide toward a small smile.','smile'),('aɪ','igh, i-e, y','kite','🪁','Open wide, then glide toward a smile.','open'),('ɔɪ','oi, oy','coin','🪙','Start with round lips. Glide toward a smile.','round'),('əʊ','oa, ow, o-e','boat','⛵','Start relaxed, then round your lips.','round'),('aʊ','ou, ow','cow','🐄','Open wide, then round your lips.','open'),('ɪə','ear, eer','ear','👂','Start with a small smile, then relax your mouth.','smile'),('eə','air, are','chair','🪑','Start with your mouth a little open. Relax as you finish.','open'),('ʊə','ure, our','pure','💧','Start with rounded lips, then relax your mouth.','round')]
phonemes=[]
for i,(ipa,letters,example,picture,cue,mouth) in enumerate(PHONEMES):
 phonemes.append(dict(id=f'p{i+1:02}',ipa=ipa,letters=letters,example=example,picture=picture,cue=cue,mouth=mouth,model=f'Listen to {example}. The sound is in {example}.',kind='consonant' if i<24 else 'vowel'))
pairs=[dict(a=a,b=b,sound=sound,cue=cue) for a,b,sound,cue in [('vet','wet','v / w','For v, top teeth touch your bottom lip. For w, round both lips.'),('pat','bat','p / b','For p, use a small puff. For b, feel your voice buzz.'),('ten','den','t / d','For t, use air. For d, turn your voice on.'),('sip','ship','s / sh','For s, keep lips relaxed. For sh, round your lips a little.'),('thin','tin','th / t','For th, let your tongue peek between your teeth.'),('ship','sheep','short i / long ee','Keep ship short and relaxed. Smile and hold the sound in sheep.'),('bit','beat','short i / long ee','Keep bit short. Stretch the middle sound in beat.'),('cap','cape','short a / long a','Cape has a gliding long a sound.'),('full','fool','short oo / long oo','Keep full short. Hold the middle sound in fool.'),('fan','van','f / v','For f, blow gently. For v, add a buzz.')]]
ROOT.mkdir(parents=True,exist_ok=True)
for name,data in [('words',words),('patterns',patterns),('sentences',sentences),('phonemes',phonemes),('minimal_pairs',pairs)]:
 (ROOT/f'{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(f'{len(words)} words, {len(sentences)} sentences, {len(phonemes)} phonemes, {len(patterns)} patterns')
assert 400<=len(words)<=600 and 100<=len(sentences)<=200 and len(phonemes)==44
